def calculate_S_prime(m):
    # S' = sum_{j=0}^m b_j * [ j * 7^(j-1) + (m-j) * 7^j ]
    # We calculate the coefficients C_j = j * 7^(j-1) + (m-j) * 7^j
    coeffs = {}
    for j in range(m + 1):
        # Handle j=0 case for 7^(j-1)
        if j == 0:
            term1 = 0
        else:
            term1 = j * (7**(j-1))

        term2 = (m - j) * (7**j)

        coeffs[j] = term1 + term2
    return coeffs

print("m=2 coeffs:", calculate_S_prime(2))
print("m=3 coeffs:", calculate_S_prime(3))
